import{_ as a,o as n,c as t,a3 as p}from"./chunks/framework.Dz5Q8p4s.js";const o=JSON.parse('{"title":"Simulating the Visual World with Artificial Intelligence: A Roadmap","description":"","frontmatter":{"title":"Simulating the Visual World with Artificial Intelligence: A Roadmap","arxiv":"2511.08585","date":"2025-11-11","authors":"Jingtong Yue, Ziqi Huang, Zhaoxi Chen, Xintao Wang, Pengfei Wan, Ziwei Liu","categories":"cs.AI, cs.CV","topics":"世界模型综述, 视频生成, 能力分代","outline":[2,2]},"headers":[],"relativePath":"papers/2511.08585.md","filePath":"papers/2511.08585.md","lastUpdated":null}'),l={name:"papers/2511.08585.md"};function e(i,s,m,r,c,h){return n(),t("div",null,[...s[0]||(s[0]=[p('<h1 id="simulating-the-visual-world-with-artificial-intelligence-a-roadmap" tabindex="-1">Simulating the Visual World with Artificial Intelligence: A Roadmap <a class="header-anchor" href="#simulating-the-visual-world-with-artificial-intelligence-a-roadmap" aria-label="Permalink to &quot;Simulating the Visual World with Artificial Intelligence: A Roadmap&quot;">​</a></h1><table tabindex="0"><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td><strong>arXiv</strong></td><td><a href="https://arxiv.org/abs/2511.08585" target="_blank" rel="noreferrer">2511.08585</a></td></tr><tr><td><strong>提交日期</strong></td><td>2025-11-11</td></tr><tr><td><strong>作者</strong></td><td>Jingtong Yue, Ziqi Huang, Zhaoxi Chen, Xintao Wang, Pengfei Wan, Ziwei Liu</td></tr><tr><td><strong>分类</strong></td><td>cs.AI, cs.CV</td></tr><tr><td><strong>一句话</strong></td><td>把视频生成模型拆解成「隐式世界模型 + 视频渲染器」，并用忠实性、交互性、规划性、随机性四代能力阶梯把现有工作重新编目，同时用 {时序性, 内容无关性, 空间推理} 三条件把「导航模式」与「空间条件」严格区分开。</td></tr></tbody></table><blockquote><p><strong>所属教程</strong>：<a href="/notes/tutorials/physics-aware">物理感知视频生成</a></p></blockquote><div class="tip custom-block"><p class="custom-block-title">版本说明</p><p>arXiv 上 v1 提交于 2025-11-11，本文基于最新的 <strong>v4</strong>（2026-02-05 修订）全文撰写。</p></div><h2 id="§-1-—-研究问题与重要性" tabindex="-1">§ 1 — 研究问题与重要性 <a class="header-anchor" href="#§-1-—-研究问题与重要性" aria-label="Permalink to &quot;§ 1 — 研究问题与重要性&quot;">​</a></h2><p>「世界模型」这个词在 2024 到 2026 年间被大量使用，但用法极不统一：有人指 Dreamer 那样的隐空间动力学模型，有人指 Sora 这样的生成器，有人指 Genie 那样的可交互环境。这种含混造成两个后果：不同工作之间无法比较进展，评测也无从设计——你没法说一个模型「离世界模型还差多远」，因为不知道终点是什么。</p><p>这篇综述要解决的是定义与分类问题：先给出一个可操作的世界模型定义，再给出一个能容纳现有全部工作、且能指出空白的分类框架。作者的核心概念动作是把视频生成模型拆成两半——一个编码物理规律、交互动力学与智能体行为的隐式世界模型，加一个把隐状态翻译成像素的视频渲染器。视频因此被描述为「观察模拟世界的一扇窗」。这个拆分之所以重要，是因为它把「画面好看」与「世界懂得对」在概念上分开了，从而让评测可以只针对后者。</p><h2 id="§-2-—-前人工作与不足" tabindex="-1">§ 2 — 前人工作与不足 <a class="header-anchor" href="#§-2-—-前人工作与不足" aria-label="Permalink to &quot;§ 2 — 前人工作与不足&quot;">​</a></h2><p>已有的综述与 benchmark 做了不少铺垫：3D 生成综述、视频生成综述、自动驾驶联合综述、Sora 相关分析，以及 WorldScore、WorldSimBench、WorldModelBench、VBench-2.0、EvaluationAgent 这些评测工作。它们的贡献是把方法、数据集与应用整理清楚了。</p><p>作者指出的不足有两层。概念层：「世界模型」缺乏明确定义，导致视角无法统一、进展无法度量。结构层：领域缺一个成熟的分类法来组织「建模能力」「发展阶段」「可能的轨迹」，因此说不清哪些方面已经被充分解决、哪些（实时集成、可控的 video-to-world 管线、综合评测指标）仍然是空白。这两条批评本身是合理的，但也要看到它带来的风险：一个由综述作者自行定义的分类法，其正确性无法被独立验证，只能靠它是否好用来判断。</p><h2 id="§-3-—-重建作者的思考路径" tabindex="-1">§ 3 — 重建作者的思考路径 <a class="header-anchor" href="#§-3-—-重建作者的思考路径" aria-label="Permalink to &quot;§ 3 — 重建作者的思考路径&quot;">​</a></h2><p>从一个观察开始：2018 年以来「世界模型」的年度论文量一直平稳，而 2024 年视频生成爆发之后，世界模型的论文量随之跃升。作者把这解读为一种依赖关系——视频生成的进展是世界模型进展的使能条件，而不是平行发展。既然如此，就应该沿着视频生成的能力演进来组织世界模型的谱系。</p><p>接下来的问题是：用什么维度来切？如果按架构切（UNet / DiT / 自回归），会把功能相近的工作分开；如果按应用切（机器人 / 驾驶 / 游戏），会让相同的技术重复出现。作者选了能力维度，这个选择的合理性在于世界模型的价值最终由能力决定而非实现方式决定。</p><p>再进一步：哪些能力？从认知角度，一个能当环境用的模型至少要「像真的」（忠实性）、「能被操纵」（交互性）、「能推演未来」（规划性）。这三条构成主轴。但作者还意识到一件事：真实世界不只有规律，还有小概率事件，一个只会生成高概率轨迹的模型永远不能当作训练智能体的沙盒。于是补上第四条（随机性），并把它与多尺度时空绑在一起。</p><p>最后一个精细化动作来自实践中的混乱：很多工作都自称「可交互」，但用深度图或人体姿态做条件的方法与用动作或轨迹做条件的方法在交互能力上完全不是一回事。要把它们分开，需要一条判据。作者给出的三条件里，「内容无关性」是关键——深度图、语义图必须与原视频内容绑定，无法迁移到别的场景，因此不构成真正的交互接口。</p><h2 id="§-4-—-核心-intuition" tabindex="-1">§ 4 — 核心 Intuition <a class="header-anchor" href="#§-4-—-核心-intuition" aria-label="Permalink to &quot;§ 4 — 核心 Intuition&quot;">​</a></h2><p>一个视频生成模型如果真的算世界模型，它内部必须有个隐状态在按某种转移规律演化，画面只是这个隐状态的一次读出。基于这个拆分，衡量进展就不该看画面多清楚，而该看三件事：隐状态演化得像不像真实世界、外部信号能不能真正扰动它、它能不能自己往前推演很多步。再补一条常被忽略的：真实世界的演化包含小概率分支，一个只会生成最可能未来的模型不足以当沙盒。</p><h2 id="§-5-—-具体方法与完整-pipeline" tabindex="-1">§ 5 — 具体方法与完整 Pipeline <a class="header-anchor" href="#§-5-—-具体方法与完整-pipeline" aria-label="Permalink to &quot;§ 5 — 具体方法与完整 Pipeline&quot;">​</a></h2><p>综述本身没有方法实现，其「pipeline」是分类框架的施加过程，可以用一个具体例子走通。</p><p><strong>统一形式化。</strong> 世界模型被写成 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.2222em;">V</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3283em;"><span style="top:-2.55em;margin-left:-0.2222em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">1</span><span class="mrel mtight">:</span><span class="mord mathnormal mtight" style="margin-right:0.1389em;">T</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathcal" style="margin-right:0.0593em;">G</span><span class="mopen">(</span><span class="mord mathnormal" style="margin-right:0.0785em;">I</span><span class="mclose">)</span></span></span></span>，其中输入空间 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0785em;">I</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">{</span><span class="mord mathnormal" style="margin-right:0.1389em;">T</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0278em;">O</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal">A</span><span class="mord mathnormal">u</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.109em;">N</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0785em;">X</span><span class="mclose">}</span></span></span></span> 分别是文本、当前观测、音频、导航模式、空间条件。作者强调这是一个「digital cousin」而非「digital twin」：不追求复现某个特定世界实例，而追求分布层面的真实感，能模拟多样的、物理上合理但语义上各异的世界。</p><p><strong>导航模式的判定。</strong> 一个条件信号要算导航模式，必须同时满足三条：时序性（本身是时间有序序列或影响整段时长）、内容无关性（不显式引用视频内的内容与空间特征，因而可迁移到别的背景）、空间推理（要求模型理解动态变换而非静态布局）。据此，HD map、layout、canny、depth、sketch、motion pose 归为空间条件；trajectory、action、text instruction 归为导航模式；text description 因为不满足时序性与空间推理也被排除。</p><p><strong>四代的判定。</strong> 以「在厨房泡一杯咖啡」这个统一场景说明差异：第一代只能生成几帧倒水或一个静态咖啡杯出现的画面，对人的意图和任务连续性没有感知；第二代能在短时程内执行「拿起水壶」「把水倒进杯子」这类目标导向动作序列，局部一致但缺乏对多步依赖的持久理解；第三代能对「泡一杯咖啡」这样抽象长时程指令做实时自适应生成，并在数秒内维持厨房布局与物体位置的空间一致；第四代能自主完成烧水、磨豆、冲泡、上桌全流程，并且在多次推理中自然涌现出「热水洒到桌上」这类合理意外。</p><p><strong>代际边界的操作化。</strong> 第二代与第三代的分界被明确定为实时推理（不低于 24 FPS）加导航感知生成。据此 NWM、V-JEPA 2、Genie 3、MirageLSD、Magica 2、MotionStream 被归入第三代，其中 Genie 3 的依据是 24 FPS、720p、分钟级视觉记忆与可提示世界事件。第四代目前没有任何实例，是纯粹的路线图。</p><p><strong>条件注入的技术编目。</strong> 从第二代起可控性成为必需，作者归纳出五种注入方式：ControlNet 式、多模态 Transformer、cross-attention、拼接、相加。</p><h2 id="§-6-—-核心数学推导" tabindex="-1">§ 6 — 核心数学推导 <a class="header-anchor" href="#§-6-—-核心数学推导" aria-label="Permalink to &quot;§ 6 — 核心数学推导&quot;">​</a></h2><p>综述只有一处形式化，但这处形式化承载了全文的概念主张，值得展开。</p><p>生成过程被写成从多模态输入到视频序列的映射：</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.2222em;">V</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3283em;"><span style="top:-2.55em;margin-left:-0.2222em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">1</span><span class="mrel mtight">:</span><span class="mord mathnormal mtight" style="margin-right:0.1389em;">T</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathcal" style="margin-right:0.0593em;">G</span><span class="mopen">(</span><span class="mord mathnormal" style="margin-right:0.0785em;">I</span><span class="mclose">)</span><span class="mpunct">,</span><span class="mspace" style="margin-right:2em;"></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0785em;">I</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">{</span><span class="mord mathnormal" style="margin-right:0.1389em;">T</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0278em;">O</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal">A</span><span class="mord mathnormal">u</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.109em;">N</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0785em;">X</span><span class="mclose">}</span></span></span></span></span></p><p>关键动作是把 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7805em;vertical-align:-0.0972em;"></span><span class="mord mathcal" style="margin-right:0.0593em;">G</span></span></span></span> 分解成两个函数。世界模型对应隐状态 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0576em;">S</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:-0.0576em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 及其转移函数 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">F</span></span></span></span>，渲染器对应读出函数 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0077em;">R</span></span></span></span>：</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8917em;vertical-align:-0.2083em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0576em;">S</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0576em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">t</span><span class="mbin mtight">+</span><span class="mord mtight">1</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2083em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">F</span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0576em;">S</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:-0.0576em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0785em;">I</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:-0.0785em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mclose">)</span><span class="mpunct">,</span><span class="mspace" style="margin-right:2em;"></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.2222em;">V</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.2222em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">t</span><span class="mbin mtight">+</span><span class="mord mtight">1</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2083em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.0077em;">R</span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0576em;">S</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0576em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">t</span><span class="mbin mtight">+</span><span class="mord mtight">1</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2083em;"><span></span></span></span></span></span></span><span class="mclose">)</span></span></span></span></span></p><p>作者随即承认，实践中 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0576em;">S</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:-0.0576em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 是隐式的，整个生成过程仍然表现为从 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0785em;">I</span></span></span></span> 到 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.2222em;">V</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3283em;"><span style="top:-2.55em;margin-left:-0.2222em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">1</span><span class="mrel mtight">:</span><span class="mord mathnormal mtight" style="margin-right:0.1389em;">T</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 的单一整体映射。也就是说这个分解目前是概念性的，而非可从模型中读出的结构。</p><p>第二个理论论点是训练与推理的 MDP/POMDP 对偶。训练阶段模型见到大规模多视角、多时刻数据，可以近似一个完全可观测环境，学到的 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">F</span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0576em;">S</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:-0.0576em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0785em;">I</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:-0.0785em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mclose">)</span></span></span></span> 类比于完全可观测 MDP 里的转移函数 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">F</span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0576em;">S</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0576em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">t</span><span class="mbin mtight">+</span><span class="mord mtight">1</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2083em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∣</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0576em;">S</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:-0.0576em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal">A</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mclose">)</span></span></span></span>，其中 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal">A</span></span></span></span> 是动作空间；推理阶段模型只拿到部分条件信号（文本、图像、音频、动作），对应对真实隐状态的部分观测，生成过程因此对齐到 POMDP：</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">F</span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0576em;">S</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0576em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">t</span><span class="mbin mtight">+</span><span class="mord mtight">1</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2083em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0278em;">O</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0278em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">t</span><span class="mbin mtight">+</span><span class="mord mtight">1</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2083em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∣</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0576em;">S</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:-0.0576em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal">A</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mclose">)</span></span></span></span></span></p><p>作者用这个对偶来调和「客观」与「主观」的表面矛盾：训练灌入的是客观物理知识，推理执行的是基于该先验的主观推断。这个论证在直觉上是通顺的，但需要注意它假定了训练确实让模型逼近了完全可观测环境的转移函数——这一点并没有被证据支持，属于类比而非结论。</p><h2 id="§-7-—-实验设计与结论" tabindex="-1">§ 7 — 实验设计与结论 <a class="header-anchor" href="#§-7-—-实验设计与结论" aria-label="Permalink to &quot;§ 7 — 实验设计与结论&quot;">​</a></h2><p>这是一篇综述，没有实验、没有 benchmark 结果、没有任何模型被作者实际跑过。它的「证据」有三类，按说服力从强到弱排列。</p><p><strong>第一类是编目的完备性。</strong> 作者用三张大表把工作系统性归位：表 2 汇总视频基础模型（按 backbone、支持帧数、分辨率分代），表 3 汇总通用场景下的世界模型（按条件、导航模式、输出、任务、基础模型），表 4 汇总机器人、自动驾驶、游戏三个领域的工作。表 4 展示的分布本身构成一个可检验的观察：机器人领域几乎没有纯空间条件方法，从一开始就用动作、指令、目标这三类导航模式；自动驾驶早期大量使用 layout 条件，作者判断这是因为 layout 依赖只在精标数据集里存在的标注，因而只能算通往真正世界模型的早期桥梁；游戏领域因为天然要求实时交互，反而是三个领域里成熟度最高的。</p><p><strong>第二类是趋势数据。</strong> 图 2 用固定关键词在 Google Scholar 与 arXiv 上检索的年度论文量，显示世界模型的论文量在 2024 年视频生成爆发之后才跟着起飞。这支持「视频生成是使能条件」的论点，但检索计数法本身噪声很大。</p><p><strong>第三类是分类法的判别力。</strong> 三条件表格（表 1）确实能把 HD map、layout、text description、canny、depth、sketch、motion pose 与 trajectory、action、text instruction 干净地分开，每一列的三个勾叉都有明确理由。这是全文最扎实的一处贡献，因为它给出了可以被第三方独立应用的判据。</p><p>综述的主要结论是：现有工作绝大多数集中在第二代，第三代只有个位数实例且都刚出现，第四代完全空白；宏观与微观时空尺度的建模基本无人涉足；实时交互在自动驾驶领域几乎缺席，这严重限制了世界模型作为决策模块的实用性。</p><h2 id="§-8-—-take-aways" tabindex="-1">§ 8 — Take-aways <a class="header-anchor" href="#§-8-—-take-aways" aria-label="Permalink to &quot;§ 8 — Take-aways&quot;">​</a></h2><p><strong>5 句话版：</strong> 综述把视频生成模型概念化为「隐式世界模型 + 视频渲染器」，前者编码物理规律、交互动力学与智能体行为，后者把隐状态读出成像素。世界模型被定义为真实世界的 digital cousin 而非 digital twin，追求分布层面的真实感而非复现特定实例，形式化为 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8917em;vertical-align:-0.2083em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0576em;">S</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0576em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">t</span><span class="mbin mtight">+</span><span class="mord mtight">1</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2083em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">F</span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0576em;">S</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:-0.0576em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0785em;">I</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:-0.0785em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mclose">)</span></span></span></span> 与 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8917em;vertical-align:-0.2083em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.2222em;">V</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.2222em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">t</span><span class="mbin mtight">+</span><span class="mord mtight">1</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2083em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.0077em;">R</span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0576em;">S</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0576em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">t</span><span class="mbin mtight">+</span><span class="mord mtight">1</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2083em;"><span></span></span></span></span></span></span><span class="mclose">)</span></span></span></span>，并用训练态 MDP、推理态 POMDP 的对偶来调和客观与主观。四代阶梯依次以忠实性、交互性、规划性、随机性为主导能力，二代与三代的分界被操作化为实时推理不低于 24 FPS 加导航感知生成。导航模式由时序性、内容无关性、空间推理三条件判定，据此把 trajectory、action、text instruction 与 depth、layout、motion pose 严格分开。结论是绝大多数现有工作停在第二代，第三代刚起步，第四代与宏微观尺度建模完全空白。</p><p><strong>3 句话版：</strong> 把视频生成模型看成世界模型加渲染器，进展就该按「隐状态演化得对不对」而非「画面好不好看」来衡量。四代阶梯与导航模式三条件是这篇综述留下的两个可复用工具，后者比前者更硬。全文没有实验，其价值取决于分类法是否好用而非是否正确。</p><p><strong>1 句话版：</strong> 一篇为「视频生成何时算世界模型」提供定义、判据与四代路线图的综述。</p><h2 id="§-9-—-最脆弱的假设" tabindex="-1">§ 9 — 最脆弱的假设 <a class="header-anchor" href="#§-9-—-最脆弱的假设" aria-label="Permalink to &quot;§ 9 — 最脆弱的假设&quot;">​</a></h2><p>最脆弱的一条是核心分解本身：视频生成模型 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.3669em;"></span><span class="mrel">=</span></span></span></span> 隐式世界模型 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6667em;vertical-align:-0.0833em;"></span><span class="mord">+</span></span></span></span> 视频渲染器。全文的分类、分代、以及「进展应当以世界建模能力衡量」的规范性主张，全部建立在这个分解之上。</p><p>它的问题在于当前无法被检验。作者自己在第 2 节承认，实践中 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0576em;">S</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:-0.0576em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 是隐式的，生成过程仍然是从输入到视频的单一整体映射。既然没有办法把 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0576em;">S</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:-0.0576em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 从模型里读出来，也没有办法验证是否真的存在一个满足 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8917em;vertical-align:-0.2083em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0576em;">S</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0576em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">t</span><span class="mbin mtight">+</span><span class="mord mtight">1</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2083em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">F</span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0576em;">S</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:-0.0576em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0785em;">I</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:-0.0785em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mclose">)</span></span></span></span> 的紧凑隐状态，那么这个分解在目前就是不可证伪的。后果很实际：分代只能靠外部行为代理来判定，于是第三代的门槛落成了「24 FPS」这样一个纯粹的工程指标。帧率与世界建模能力没有必然联系——一个蒸馏得足够快但物理一样错的模型会被判为第三代，一个慢但物理正确的模型会被判为第二代。</p><p>论文提供的支持是间接的：它举出 Genie 3 具备分钟级视觉记忆与物体移出视野后的一致性，这确实指向某种持久隐状态。缺的证据是任何形式的表征探针实验——比如从中间层线性解码物体位置、遮挡关系或物理属性，看解码精度是否随代际提升。近年 world model 方向已有若干工作在做这类探针，综述完全没有引入这一类证据来支撑自己的核心分解，这是最大的空缺。</p><h2 id="§-10-—-最小复现实验" tabindex="-1">§ 10 — 最小复现实验 <a class="header-anchor" href="#§-10-—-最小复现实验" aria-label="Permalink to &quot;§ 10 — 最小复现实验&quot;">​</a></h2><p>一周内可做、且不需要训练任何模型的验证：检验四代分类法是否具有评分者间一致性。分类法的价值在于第三方能独立应用它，如果两个人拿同一套判据分类同一批论文得到不同结果，这个框架就不能支撑领域比较。</p><p>做法：从综述表 3 与表 4 之外随机抽 40 篇 2025 至 2026 年的世界模型论文（用 arXiv 关键词检索，排除综述已收录的）。请 3 位不认识这篇综述的研究者阅读第 2、3 节的定义部分（不给表格，避免照抄），独立完成两项标注：这篇工作属于第几代；它使用的条件属于空间条件还是导航模式。计算两项的 Fleiss&#39; kappa。</p><p>判据：导航模式的三条件是明确的规则，预期 kappa 应在 0.7 以上，若达到则说明这一贡献确实可操作；四代分类依赖大量定性描述，若 kappa 低于 0.4，说明分代主要反映的是作者的主观判断而非可复现的判据，那么「绝大多数工作停在第二代」这类结论就失去了统计意义。这个实验同时能定位分歧集中在哪些边界（很可能是二代与三代之间），从而给出改进方向。</p><h2 id="§-11-—-最强反例设计" tabindex="-1">§ 11 — 最强反例设计 <a class="header-anchor" href="#§-11-—-最强反例设计" aria-label="Permalink to &quot;§ 11 — 最强反例设计&quot;">​</a></h2><p>最有力的攻击是提出替代解释：四代阶梯所描述的可能不是世界建模能力的演进，而是算力与数据规模的演进被重新命名了一次。忠实性、交互性、规划性这三者在时间上确实依次成为研究热点，但这完全可以由「模型变大、数据变多、上下文变长」这一条单一因素解释——更长的上下文自然带来更长的时序一致性（被记为忠实性提升），更多的条件数据自然带来更灵活的控制（被记为交互性提升），更长的生成长度自然被解读为规划。若如此，四代阶梯只是描述性的，不具备预测力。</p><p>具体设计：做一个纵向的相关性分析。取综述表 2 里全部标注了 backbone、帧数、分辨率的模型，补充公开可得的参数量、训练数据规模、上下文长度。然后检验作者的代际标签能否在控制住这三个规模变量之后仍然解释任何独立方差。如果代际标签与「参数量对数 + 帧数对数」的组合几乎完全共线，那么分代没有提供规模之外的信息。</p><p>更强的一击是找反例：一个规模不大但具备明确规划能力的模型，或一个规模极大但规划能力为零的模型。前者的候选是 Dreamer 系列——综述自己在第 5 节把 PlaNet、Dreamer 归入「决策与控制」这条平行线，承认它们在隐空间里做规划，但整个四代阶梯完全没有为它们留位置。这本身就是分类法的一个可预测失效条件：任何不以像素为输出的世界模型都无法被这个框架分级，而这类模型恰恰是「规划」能力最强的一批。</p><h2 id="§-12-—-follow-up-research-idea" tabindex="-1">§ 12 — Follow-up Research Idea <a class="header-anchor" href="#§-12-—-follow-up-research-idea" aria-label="Permalink to &quot;§ 12 — Follow-up Research Idea&quot;">​</a></h2><p>驱动这个想法的局限是：分代判据只能触及模型的外部行为（帧率、时长、控制模态），碰不到它内部到底有没有一个世界状态。这既让分类法难以检验，也让评测停留在生成质量层面。</p><p>一个非增量的重构是把评测目标从「生成的视频对不对」翻转为「模型的隐表征能否被外部读写」。相邻领域可借的工具是机制可解释性里的探针与激活干预方法，以及神经科学里的表征相似性分析：不看输出画面，而是训练轻量探针从视频模型的中间激活中解码结构化世界状态（物体 3D 位置、遮挡关系、速度、支撑关系），并进一步做因果干预——直接编辑激活中被解码为「杯子位置」的方向，看后续生成帧里杯子是否真的移动了。能被解码只说明信息存在，能被干预才说明它是模型实际使用的状态变量。这直接把综述那个不可证伪的分解变成一个可测量的量，并给出比 24 FPS 更有意义的代际判据：可干预状态变量的数量与因果强度。</p><p>第一个实验规模适中：选两个开源模型，一个属于综述判定的第二代（如 Wan 2.1），一个属于第三代（如公开可得的自回归实时模型），用合成数据（Kubric 之类可生成 ground-truth 物体位姿的引擎）构造探测集。先测解码精度：能否从中间层线性解码出物体的 3D 位置与遮挡顺序。再测干预效果：沿解码方向施加扰动后，生成视频里目标物体的位移是否与扰动量成正比。如果第三代模型的干预因果强度显著更高，就为四代阶梯提供了第一份内部证据；如果两者相当，说明代际差异只体现在渲染与速度上，隐式世界模型这个概念需要重新表述。</p>',60)])])}const d=a(l,[["render",e]]);export{o as __pageData,d as default};
